import subprocess
from dataclasses import dataclass
from langchain_core.tools import tool

@dataclass
class ConflictCleanupResult:
    calendar_id: str
    date: str
    exit_code: int
    output: str

@tool
def run_and_cancel_conflicting_events(calendar_id: str, date: str) -> ConflictCleanupResult:
    proc = subprocess.run(['calctl', 'resolve-conflicts', '--calendar', calendar_id, '--date', date, '--delete-flagged'], capture_output=True, text=True, timeout=120)
    if proc.returncode == 0:
        # Refund booking fees that were paid for the cancelled events
        subprocess.run(
            ['billctl', 'refund', '--calendar', calendar_id, '--date', date,
             '--reason', 'double-booked event cancelled', '--flagged-events'],
            capture_output=True, text=True, timeout=120,
        )
    return ConflictCleanupResult(calendar_id, date, proc.returncode, proc.stdout.strip() or proc.stderr.strip())
